-- 863: Blog post — "UTAP AI Tool Subscription Claim" step-by-step guide, linking to the
--      SG AI course catalogue and three UTAP-tagged WSQ AI courses.
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line — the content HTML below is
--    intentionally ONE line. Do not reformat it.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance (set from MMS_COUNTRY_CODE by apply.php) — partner
--    instances (MY/GH) have no UTAP scheme. Local dev reports SG, so the post is
--    previewable on localhost.
--  * Published immediately (status 1) — this is a hand-written post, not a pipeline draft,
--    so it does not go through the manager review loop.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'UTAP AI Tool Subscription Claim: A Step-by-Step Guide for NTUC Members (2026)', 'utap-ai-tool-subscription-claim-guide-singapore', 'NTUC members can now claim 50% of their AI tool subscriptions — ChatGPT Plus, Claude Pro, Copilot and more — under UTAP, capped at $250 a year (or $500 if you are 40 and above). The catch: you must first complete a UTAP-approved AI course. Here is the full claim process, screen by screen, and the courses that unlock it.', '<p><strong>Short version:</strong> if you are a paid-up NTUC member and you complete a UTAP-approved AI course, NTUC will reimburse <strong>50% of what you pay for an approved AI tool subscription</strong> — up to <strong>$250 a year</strong> if you are below 40, or <strong>$500 a year</strong> if you are 40 and above. The support window runs from <strong>1 May 2026 to 30 April 2028</strong>. Below is exactly how to claim it.</p> <h2>What is the UTAP AI tool subscription claim?</h2> <p>The Union Training Assistance Programme (UTAP) is NTUC''s training benefit for members. It has always covered course fees; from <strong>1 May 2026</strong> it also covers <strong>AI tool subscriptions</strong> — the paid plans professionals actually use day to day, such as ChatGPT Plus, Claude Pro, Microsoft 365 Copilot, Gemini and similar approved tools.</p> <p>The logic behind the scheme is simple: NTUC does not want members to merely <em>attend</em> an AI course and then go back to working the old way. It wants the tool in your hands afterwards. So the subsidy is deliberately sequenced — <strong>learn first, subscribe second, claim third</strong>.</p> <h2>How much can you claim?</h2> <table> <tr><th>Your age</th><th>UTAP support</th><th>Annual cap</th></tr> <tr><td>Below 40</td><td>50% of the subscription fee</td><td>$250 per calendar year</td></tr> <tr><td>40 and above</td><td>50% of the subscription fee</td><td>$500 per calendar year</td></tr> </table> <p><strong>Important:</strong> this cap is <em>shared</em>. The same $250 / $500 annual ceiling covers your UTAP course-fee claims <em>and</em> your AI tool subscription claims combined — it is not a separate top-up. If you have already used your full UTAP allowance on course fees this year, plan your subscription claim for the next calendar year.</p> <h2>Are you eligible? The five conditions</h2> <ol> <li><strong>Paid-up NTUC membership</strong> — before the course starts, throughout the whole course, <em>and</em> at the point you submit the claim. A lapsed month in between is the most common reason claims get rejected.</li> <li><strong>You completed a UTAP-approved AI course</strong> — with at least <strong>75% attendance</strong> and a Certificate of Completion.</li> <li><strong>You subscribed within one year</strong> of completing that course.</li> <li><strong>The subscription start date falls between 1 May 2026 and 30 April 2028</strong> (both dates inclusive).</li> <li><strong>The subscription is for your own use</strong> — you must declare this. Company-paid or fully-sponsored subscriptions do not qualify.</li> </ol> <h2>Step 1: Complete a UTAP-approved AI course</h2> <p>Nothing else in this guide works until this step is done — the claim form literally asks <em>"Attended UTAP Approved AI Course?"</em> and requires your certificate as an upload.</p> <p>Our WSQ AI courses are UTAP-eligible and, for Singaporeans and PRs, already carry <strong>up to 70% SkillsFuture (WSQ) course fee funding</strong> before UTAP is applied. Popular starting points:</p> <ul> <li><a href="{{store direct_url=''wsq-agentic-ai-for-business-process-automation.html''}}"><strong>WSQ - Agentic AI for Business Process Automation</strong></a> — build AI agents that take real work off your plate</li> <li><a href="{{store direct_url=''wsq-agentic-ai-for-social-media-marketing.html''}}"><strong>WSQ - Agentic AI for Social Media Marketing</strong></a> — for marketers who want AI running the content engine</li> <li><a href="{{store direct_url=''wsq-end-to-end-creative-image-generation-with-agentic-ai-and-vibe-coding.html''}}"><strong>WSQ - End-to-End Creative Image Generation with Agentic AI and Vibe Coding</strong></a> — for designers and content creators</li> </ul> <p>Browse the full catalogue of <a href="{{store direct_url=''artificial-intelligence-courses.html''}}"><strong>AI courses in Singapore</strong></a> — over 200 courses across generative AI, agentic AI, AI marketing, data science and AI-assisted coding. Check the course page or ask our team to confirm UTAP approval before you enrol.</p> <h2>Step 2: Subscribe to an approved AI tool</h2> <p>Once you have your certificate, subscribe to an approved AI tool <strong>within one year</strong>. Pick the tool you will genuinely use for work — the whole point of the scheme is adoption, and you will need the payment records at claim time. Keep the tax invoice or receipt, and note the exact <strong>subscription start date</strong>: your six-month claim clock starts from that date, not from your course completion date.</p> <h2>Step 3: Submit your claim on the NTUC U Portal</h2> <p>The claim is made online. Here is the exact click path:</p> <ol> <li>Visit the <strong>NTUC Member Portal</strong> at <a href="https://www.ntuc.org.sg/uportal" target="_blank" rel="noopener">ntuc.org.sg/uportal</a></li> <li>Click <strong>E-Services</strong></li> <li>Log in using your <strong>Singpass</strong></li> <li>Click <strong>Apply Here</strong> under <strong>Union Training Assistance Programme (UTAP)</strong></li> <li>Select <strong>AI Tools Subscription Claim</strong></li> <li>Choose <strong>"Yes"</strong> for <em>"Attended UTAP Approved AI Course?"</em></li> <li>Upload your <strong>Certificate of Completion</strong> for the module, then complete your <strong>AI Course Details</strong> and <strong>AI Tool Subscription Details</strong>, and check that your <strong>bank account details</strong> are accurate for reimbursement</li> <li>Review your application and click <strong>Submit</strong></li> </ol> <h3>Before you hit Submit, have these ready</h3> <ul> <li>Your <strong>Certificate of Completion</strong>, saved and ready to upload</li> <li>Your <strong>AI tool subscription details</strong> — tool name, subscription start date, payment/receipt details</li> <li>Your <strong>bank account information</strong>, correct and current — wrong bank details are the number one cause of delayed reimbursements</li> </ul> <p>Stuck at any point? Call the <strong>NTUC Membership Hotline at 6213 8008</strong>.</p> <h2>The two deadlines that catch people out</h2> <table> <tr><th>Clock</th><th>You have</th><th>Counted from</th></tr> <tr><td>Course &rarr; subscription</td><td>12 months</td><td>Your course completion date</td></tr> <tr><td>Subscription &rarr; claim</td><td>6 months</td><td>Your subscription <em>start</em> date</td></tr> </table> <p>Miss either window and the claim is gone — there is no appeal for a late submission. The safest habit: submit the claim in the same week your subscription is charged, while the receipt is still in your inbox.</p> <h2>Worked example</h2> <p>Priya, 43, is a marketing manager and a paid-up NTUC member. In June 2026 she completes a UTAP-approved WSQ agentic AI course with full attendance. In July 2026 she subscribes to an approved AI assistant at $30/month and commits to a year — $360. She submits her UTAP AI Tools Subscription Claim in August 2026, well inside the six-month window. At 50% support her claim is $180, which sits comfortably under her $500 annual cap (she is 40 and above). Net cost of her tooling for the year: <strong>$180</strong> — and the course fee itself was already WSQ-funded.</p> <h2>Frequently asked questions</h2> <h3>Can I claim if my employer paid for the AI tool?</h3> <p>No. You must declare that the subscription is for your own use. Fully sponsored or company-funded subscriptions are not claimable under this scheme.</p> <h3>Does the AI tool subsidy come on top of my course fee claim?</h3> <p>No — both draw on the same annual cap of $250 (below 40) or $500 (40 and above). Sequence your claims across calendar years if you want to maximise both.</p> <h3>What if I took the AI course before 1 May 2026?</h3> <p>The subscription start date is what must fall within 1 May 2026 to 30 April 2028, and it must be within one year of your course completion. So an earlier course can still qualify, provided the one-year gap and the scheme window both hold.</p> <h3>Do I need 75% attendance?</h3> <p>Yes. UTAP requires at least 75% attendance for the course, and you need the Certificate of Completion to upload with the claim.</p> <h3>Which of your courses are UTAP-approved?</h3> <p>Our WSQ AI courses are UTAP-eligible. Check the individual course page or contact our team to confirm approval status for the specific run you are enrolling in — approval is confirmed per course and per intake.</p> <h2>Start here</h2> <p>The subsidy rewards people who actually build AI into their work. The sequence is fixed, so the first move is always the course.</p> <ol> <li>Pick your course from our <a href="{{store direct_url=''artificial-intelligence-courses.html''}}"><strong>AI course catalogue</strong></a> and confirm UTAP approval with our team</li> <li>Complete it with 75%+ attendance and collect your Certificate of Completion</li> <li>Subscribe to your AI tool within 12 months, then claim within 6 months of the subscription start date</li> </ol> <p><a href="{{store direct_url=''artificial-intelligence-courses.html''}}"><strong>Browse AI courses and check your funding eligibility &rarr;</strong></a></p> <p><em>Figures and scheme conditions in this article reflect NTUC UTAP terms published for the 1 May 2026 to 30 April 2028 support period and are provided for general guidance. Always confirm current terms on the NTUC U Portal, as scheme rules can change.</em></p>', 'Tertiary Infotech Academy', 1, CURDATE(), 'TGS-2024045801, TGS-2021006714, TGS-2026061583', 'UTAP AI Tool Subscription Claim Guide 2026 | Tertiary Infotech Academy', 'Step-by-step guide to claiming 50% of your AI tool subscription under NTUC UTAP in Singapore. Eligibility, caps ($250/$500), deadlines, the U Portal submission steps, and the UTAP-approved AI courses that qualify you.', 'utap, utap ai tool subscription, ntuc utap claim, ai tool subsidy singapore, ntuc ai subsidy, utap approved ai course, skillsfuture ai course, wsq ai course singapore', NOW(), NOW() FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'utap-ai-tool-subscription-claim-guide-singapore');

